const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'¥'+n.toFixed(2);
const names=[['磁吸折叠手机支架','数码配件','抖音','▱',89,19,6,14,5,3,86,29,88],['便携宠物饮水杯','宠物用品','Amazon','♧',139,35,16,22,15,4,72,37,84],['模块化桌面收纳盒','家居生活','淘宝','▤',69,16,7,9,5,3,58,34,94],['运动速干冷感毛巾','运动户外','TikTok','≈',59,12,8,13,8,4,92,65,89],['可折叠硅胶饭盒','家居生活','Amazon','▣',129,31,19,25,15,5,39,48,82],['旅行压缩收纳袋','家居生活','抖音','▥',79,18,7,17,5,4,64,59,91],['宠物慢食益智碗','宠物用品','淘宝','◉',49,11,6,8,5,3,34,43,85],['桌面氛围小夜灯','数码配件','TikTok','☼',159,49,19,38,8,6,81,74,68]];
const demo=names.map((x,i)=>{const [name,category,platform,icon,price,cost,shipping,ad,fee,returns,growth,competition,supply]=x;return{id:'demo-'+i,name,category,platform,icon,price,cost,shipping,ad,fee,returns,growth,competition,supply,source:'演示数据（非真实市场观测）',date:'2026-10-26',demo:true,saved:false,status:'待调研',note:''}});
let data=structuredClone(demo),weights=[30,25,30,15],view='all',selected=new Set();try{const s=JSON.parse(localStorage.getItem('radar-v1'));if(s){if(!Array.isArray(s.data))throw Error();s.data.forEach(Radar.validate);data=s.data;weights=s.weights?.length===4&&s.weights.every(n=>Number.isFinite(n)&&n>=0)&&s.weights.some(n=>n>0)?s.weights:weights}}catch(e){console.warn('本地数据不可用，加载演示数据')}
function persist(){try{localStorage.setItem('radar-v1',JSON.stringify({data,weights}))}catch(e){toast('浏览器存储不可用，请立即导出备份')}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function filtered(){return data.filter(p=>(view!=='saved'||p.saved)&&(!$('#search').value||p.name.includes($('#search').value))&&(!$('#category').value||p.category===$('#category').value)&&(!$('#platform').value||p.platform===$('#platform').value)&&(!$('#profitable').checked||Radar.calc(p,weights).margin>=20)).sort((a,b)=>{const k=$('#sort').value;return k==='growth'?b.growth-a.growth:Radar.calc(b,weights)[k]-Radar.calc(a,weights)[k]})}
function render(){const cats=[...new Set(data.map(p=>p.category))],cat=$('#category').value;$('#category').innerHTML='<option value="">全部类目</option>'+cats.map(c=>`<option ${c===cat?'selected':''}>${esc(c)}</option>`).join('');const list=filtered(),high=data.filter(p=>Radar.calc(p,weights).score>=75).length,avg=data.length?data.reduce((a,p)=>a+Radar.calc(p,weights).margin,0)/data.length:0;$('#metrics').innerHTML=[['已收录商品',data.length,'支持导入自有商品数据'],['高潜力线索',high,'规则评分 ≥ 75 分'],['平均单件利润率',avg.toFixed(1)+'%','已扣除投放与退货预留'],['待验证候选',data.filter(p=>p.saved&&p.status!=='已淘汰'&&p.status!=='已通过').length,'小批量验证后再做采购决策']].map(x=>`<div class="metric"><small>${x[0]}</small><strong>${x[1]}</strong><em>${x[2]}</em></div>`).join('');$('#savedCount').textContent=data.filter(p=>p.saved).length;$('#compareCount').textContent=selected.size;$('#resultCount').textContent=list.length+' 件商品';$('#viewTitle').textContent=view==='all'?'机会发现':'我的候选池';$('#listTitle').textContent=view==='all'?'潜力商品榜':'候选验证清单';$('#rows').innerHTML=list.length?list.map(p=>{const r=Radar.calc(p,weights);return`<tr><td><input aria-label="对比 ${esc(p.name)}" type="checkbox" data-select="${esc(p.id)}" ${selected.has(p.id)?'checked':''}></td><td><button class="product" data-detail="${esc(p.id)}"><span class="icon">${esc(p.icon||'◇')}</span><span>${esc(p.name)}<small>${esc(p.category)} · ${esc(p.platform)} · ${p.demo?'演示':esc(p.date)}</small></span></button></td><td><span class="score">${r.score}</span><small>${r.score>=75?'优先验证':r.score>=60?'持续观察':'谨慎评估'}</small><div class="scorebar"><i style="width:${r.score}%"></i></div></td><td class="up">${p.growth>0?'+':''}${p.growth}%<small>与前30天相比</small></td><td><span class="chip ${p.competition>=60?'high':''}">${p.competition<40?'低':p.competition<65?'中':'高'} · ${p.competition}</span></td><td>${money(p.price)}</td><td>${money(r.profit)}<small>${r.margin.toFixed(1)}% 利润率</small></td><td><button class="save" data-save="${esc(p.id)}" title="${p.saved?'移出':'加入'}候选池">${p.saved?'★':'☆'}</button>${p.saved?`<small>${esc(p.status)}</small>`:''}</td></tr>`}).join(''):'<tr><td colspan="8" class="empty">暂无符合条件的商品，请调整筛选或添加商品。</td></tr>';$('#scatter').innerHTML='<span>需求增速 ↑</span><div class="axislabel">竞争强度 →</div>'+data.map(p=>`<button class="bubble" style="padding:0;left:${Math.min(95,p.competition)}%;bottom:${Math.max(2,Math.min(85,(p.growth+100)/2.3))}%" data-detail="${esc(p.id)}" title="${esc(p.name)}：增长 ${p.growth}% / 竞争 ${p.competition}" aria-label="${esc(p.name)}"></button>`).join('')}
function modal(title,body){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;if(!$('#dialog').open)$('#dialog').showModal()}$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});
const fields=[['name','商品名称','text'],['category','商品类目','text'],['platform','销售平台','text'],['price','售价（人民币）','number'],['cost','采购成本','number'],['shipping','单件物流 / 履约','number'],['ad','单件广告获客成本','number'],['fee','平台费率（%）','number'],['returns','退货损失预留（售价%）','number'],['growth','30天需求增长率（%）','number'],['competition','竞争强度（0低—100高）','number'],['supply','供应稳定度（0—100）','number'],['source','数据来源 / 链接','text'],['date','采集日期','date']];
function form(p){modal(p?'编辑商品':'添加商品',`<p class="help">请使用同一市场、同一口径的数据。竞争与供应为人工评估指标，缺乏证据时不宜直接下采购结论。</p><form id="productForm"><div class="formgrid">${fields.map(([k,label,type])=>`<label>${label}<input name="${k}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(p?.[k]??(type==='number'?0:k==='date'?new Date().toISOString().slice(0,10):''))}" required ${k==='price'?'min="0.01"':type==='number'&&k!=='growth'?'min="0"':''} ${['fee','returns','competition','supply'].includes(k)?'max="100"':''} ${k==='growth'?'min="-100"':''}></label>`).join('')}</div><div class="actions"><button type="submit" class="primary">保存商品</button></div></form>`);$('#productForm').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));fields.filter(x=>x[2]==='number').forEach(([k])=>v[k]=Number(v[k]));try{Radar.validate(v);if(p)Object.assign(p,v,{demo:false});else data.push({...v,id:crypto.randomUUID(),saved:false,status:'待调研',note:'',demo:false});persist();render();$('#dialog').close();toast('商品已保存')}catch(e){toast(e.message)}}}
function detail(id){const p=data.find(p=>p.id===id);if(!p)return;const r=Radar.calc(p,weights);modal(p.name,`<p class="help">${esc(p.platform)} · ${esc(p.category)} · ${esc(p.date)}<br>来源：${esc(p.source)}${p.demo?' · 演示数据':''}</p><div class="summary">潜力评分 <strong>${r.score}</strong> / 100　　单件利润 <strong>${money(r.profit)}</strong><br>利润率 ${r.margin.toFixed(1)}% · 保本广告成本 ${money(p.price-p.cost-p.shipping-p.price*(p.fee+p.returns)/100)}</div><div class="breakdown">${['需求增长','竞争机会','利润空间','供应稳定'].map((n,i)=>`<div>${n} · 权重 ${weights[i]}<b>${r.parts[i].toFixed(0)}</b></div>`).join('')}</div><h2>成本拆解</h2><p class="help">售价 ${money(p.price)} − 采购 ${money(p.cost)} − 物流 ${money(p.shipping)} − 广告 ${money(p.ad)} − 平台费 ${money(p.price*p.fee/100)} − 退货损失预留 ${money(p.price*p.returns/100)} = ${money(r.profit)}<br>当前测算未单列税费、仓租、人员和汇率波动，实际决策需另行预留。</p><div class="status"><label for="stage">验证状态</label><select id="stage">${['待调研','待打样','测款中','已通过','已淘汰'].map(s=>`<option ${p.status===s?'selected':''}>${s}</option>`).join('')}</select></div><label class="help" for="note">调研记录、样品反馈、测款结果</label><textarea id="note" style="width:100%;height:90px">${esc(p.note)}</textarea><div class="actions"><button id="edit">编辑成本与数据</button><button id="saveNote" class="primary">保存验证记录</button></div>`);$('#edit').onclick=()=>form(p);$('#saveNote').onclick=()=>{p.note=$('#note').value;p.status=$('#stage').value;p.saved=true;persist();render();toast('验证记录已保存')}}
document.addEventListener('click',e=>{const d=e.target.closest('[data-detail]'),s=e.target.closest('[data-save]'),v=e.target.closest('[data-view]');if(d)detail(d.dataset.detail);if(s){const p=data.find(p=>p.id===s.dataset.save);p.saved=!p.saved;persist();render()}if(v){view=v.dataset.view;document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n===v));render()}});document.addEventListener('change',e=>{if(e.target.dataset.select){const id=e.target.dataset.select;if(e.target.checked){if(selected.size>=4){e.target.checked=false;return toast('最多同时对比4件商品')}selected.add(id)}else selected.delete(id);$('#compareCount').textContent=selected.size}});['search','category','platform','sort','profitable'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',render));$('#add').onclick=()=>form();
$('#model').onclick=()=>{modal('透明、可调整的评分模型',`<p class="help">总分 = 各项得分 × 归一化权重。所有维度限定在0–100分。<br>需求分 = (增长率 + 20) ÷ 1.2；竞争分 = 100 − 竞争强度；利润分 = 利润率 × 2；供应分 = 供应稳定度。<br>这是启发式规则，尚未经历史销量回测。负利润商品仍可能获得较高总分，请结合利润筛选使用。</p><form id="weights"><div class="formgrid">${['需求增长','竞争机会','利润空间','供应稳定'].map((n,i)=>`<label>${n}权重<input name="w${i}" type="number" min="0" max="100" step="1" required value="${weights[i]}"></label>`).join('')}</div><div class="actions"><button class="primary">应用并重新评分</button></div></form>`);$('#weights').onsubmit=e=>{e.preventDefault();const w=[...new FormData(e.target).values()].map(Number);if(!w.some(n=>n>0))return toast('至少一个权重须大于0');weights=w;persist();render();$('#dialog').close();toast('已按新权重重新评分')}};
$('#compare').onclick=()=>{const ps=data.filter(p=>selected.has(p.id));if(ps.length<2)return toast('请在表格中选择2–4件商品');modal('商品机会对比',`<div class="tablewrap"><table><thead><tr><th>指标</th>${ps.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${[['潜力评分',p=>Radar.calc(p,weights).score],['需求增长',p=>p.growth+'%'],['竞争强度',p=>p.competition],['单件利润',p=>money(Radar.calc(p,weights).profit)],['利润率',p=>Radar.calc(p,weights).margin.toFixed(1)+'%'],['供应稳定度',p=>p.supply],['数据来源',p=>esc(p.source)]].map(([n,f])=>`<tr><td>${n}</td>${ps.map(p=>`<td>${f(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)};
function download(name,value){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}$('#export').onclick=()=>{download('radar-backup-'+new Date().toISOString().slice(0,10)+'.json',{version:1,weights,data});toast('已导出全部商品、验证记录及权重')};$('#importBtn').onclick=()=>{modal('导入商品数据',`<p class="help">支持 JSON 文件，最多1000件商品。可导入本系统导出的备份，或按模板填写。导入将追加商品；相同ID会跳过，原有记录不覆盖。导入备份不会覆盖当前评分权重。</p><div class="actions"><button id="template">下载数据模板</button><button class="primary" id="choose">选择 JSON 文件</button></div>`);$('#template').onclick=()=>download('radar-template.json',{version:1,data:[{...demo[0],id:undefined,name:'填写商品名称',source:'填写来源与口径',demo:false}]});$('#choose').onclick=()=>$('#file').click()};$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5e6)throw Error('文件不能超过5MB');const parsed=JSON.parse(await f.text()),rows=Array.isArray(parsed)?parsed:parsed.data;if(!Array.isArray(rows)||!rows.length||rows.length>1000)throw Error('请提供1–1000件商品的数组');rows.forEach(Radar.validate);let count=0;const ids=new Set(data.map(p=>p.id));for(const p of rows){if(p.id&&ids.has(String(p.id)))continue;const id=p.id?String(p.id):crypto.randomUUID();ids.add(id);data.push({...p,id,status:['待调研','待打样','测款中','已通过','已淘汰'].includes(p.status)?p.status:'待调研',note:String(p.note||''),saved:!!p.saved,demo:!!p.demo});count++}persist();render();$('#dialog').close();toast(`已导入 ${count} 件商品，其余为重复ID`)}catch(err){toast('导入失败：'+err.message)}finally{e.target.value=''}};render();
